// Blue-Dragons-Wappen als base64 (PNG mit transparentem Hintergrund) für die Grafiken.
// Beide Teams nutzen dasselbe Logo.
const LOGO_B64 = '';
const LOGO_W = 362;
const LOGO_H = 380;

function getLogo() {
  return { b64: LOGO_B64, w: LOGO_W, h: LOGO_H, mime: 'image/png' };
}

module.exports = { LOGO_B64, LOGO_W, LOGO_H, getLogo };
